#!/usr/bin/env python3
# coding: utf-8

""" Golden-value parity: momentums numba kernels reproduce the former Cython
implementation exactly (captured before the Cython module was removed). """

# Third-party packages
import numpy as np

# Local packages
from fynance.features.momentums import (
    _ema_1d,
    _emstd_1d,
    _emstd_2d,
    _sma_1d,
    _sma_2d,
    _smstd_1d,
    _smstd_2d,
    _wma_1d,
    _wmstd_1d,
    _wmstd_2d,
)

_RNG = np.random.default_rng(11)
X1 = _RNG.normal(10, 2, 30).astype(np.float64)
X2 = _RNG.normal(10, 2, (30, 3)).astype(np.float64)


def test_parity_sma1_5():
    assert np.allclose(_sma_1d(X1, 5), np.array([10.068385534506, 11.393940307563, 11.745774257433, 11.054177154681, 10.724153919302, 10.499523135187, 10.183514662092, 9.67120045504, 10.174077532257, 9.55433541711, 10.391908604203, 10.125445197112, 10.42002235404, 10.066641573947, 10.653932066707, 10.212556620266, 10.58093489534, 10.227771565753, 10.221283627916, 10.647202499069, 10.113822178851, 9.178263366347, 9.417268059724, 9.210156201677, 8.167740521306, 8.190255312507, 8.608969690442, 7.973695954369, 7.644936730219, 8.427728097045]), atol=1e-10)

